    def checkAttributeRedefinitions(self, tree):
        if isinstance(tree, ast.ClassDef):
            class_attributes = set()
            for node in ast.walk(tree):
                if isinstance(node, (ast.Assign, ast.AnnAssign)):
                    for target in getAssignmentTargets(node):
                        if isinstance(target, ast.Name):
                            if target.id in class_attributes:
                                self.report(messages.ClassAttributeRedefinition,
                                            tree, target.id, node)
                            class_attributes.add(target.id)
